#!/usr/bin/env node
/**
 * v4.4 M6：把用户生成的背景图集压缩为 WebP 并生成清单。
 *
 * 用法：node scripts/assets/build-gallery.mjs <源目录>
 * 输出：apps/web/public/backgrounds/gallery/gallery-NN.webp
 *       apps/web/src/features/background/gallery.ts（AUTO-GENERATED）
 */
import fs from 'node:fs';
import path from 'node:path';
import process from 'node:process';
import { fileURLToPath } from 'node:url';
import sharp from 'sharp';

const here = path.dirname(fileURLToPath(import.meta.url));
const repoRoot = path.resolve(here, '..', '..');
const sourceDir = process.argv[2];
if (!sourceDir || !fs.existsSync(sourceDir)) {
  console.error('用法：node scripts/assets/build-gallery.mjs <源目录>');
  process.exit(1);
}

const outDir = path.join(repoRoot, 'apps/web/public/backgrounds/gallery');
const manifestPath = path.join(repoRoot, 'apps/web/src/features/background/gallery.ts');
fs.mkdirSync(outDir, { recursive: true });
fs.rmSync(outDir, { recursive: true, force: true });
fs.mkdirSync(outDir, { recursive: true });

const RULES = [
  [/中秋/, '中秋聚餐'],
  [/办公室|工位/, '办公室'],
  [/教室/, '教室'],
  [/古城/, '山顶古城'],
  [/皇都/, '山顶皇都'],
  [/小镇/, '山顶小镇'],
  [/巨龙/, '山顶巨龙'],
  [/私奔/, '私奔'],
  [/结婚|婚礼|戒指/, '婚礼'],
  [/兔耳娘/, '兔耳娘'],
  [/运动装/, '海边恋爱'],
  [/海边/, '海边嬉戏'],
  [/篝火/, '露营篝火'],
  [/露营|星光/, '露营星空'],
  [/唱歌/, '合唱'],
  [/床|睡/, '安睡'],
];

function labelOf(name) {
  return RULES.find(([pattern]) => pattern.test(name))?.[1] ?? '图集';
}

const files = fs
  .readdirSync(sourceDir)
  .filter((name) => /\.png$/i.test(name))
  .sort();

const counters = new Map();
const items = [];
for (const [index, name] of files.entries()) {
  const seq = String(index + 1).padStart(2, '0');
  const base = labelOf(name);
  const count = (counters.get(base) ?? 0) + 1;
  counters.set(base, count);
  const label = count > 1 ? `${base} ${count}` : base;
  const file = `gallery-${seq}.webp`;
  const outPath = path.join(outDir, file);
  const info = await sharp(path.join(sourceDir, name))
    .resize({ width: 1920, withoutEnlargement: true })
    .webp({ quality: 80, effort: 5 })
    .toFile(outPath);
  items.push({ id: `wallpaper.gallery.${seq}`, url: `/backgrounds/gallery/${file}`, label });
  console.log(`${file}  ${Math.round(info.size / 1024)}KB  ${label}`);
}

const header = `/** AUTO-GENERATED by scripts/assets/build-gallery.mjs — 请勿手改 */\n`;
const body = `export interface GalleryBackgroundItem {\n  id: string;\n  url: string;\n  label: string;\n}\n\nexport const GALLERY_BACKGROUND_ITEMS: readonly GalleryBackgroundItem[] = ${JSON.stringify(items, null, 2)};\n`;
fs.writeFileSync(manifestPath, header + body);

const total = fs
  .readdirSync(outDir)
  .reduce((sum, file) => sum + fs.statSync(path.join(outDir, file)).size, 0);
console.log(`\n完成：${items.length} 张，合计 ${(total / 1024 / 1024).toFixed(2)}MB`);
